import java.io.*;
import java.util.*;

public class Main {
    static class Flow {
        static final int N = 50 * 99 + 2;
        static ArrayList<Edge>[] adj;
        static int[] sz;
        static long mc;
        static boolean[] vis;
        static int[] par;
        static long[] pot, dist;

        static class Edge {
            int v, r;
            long f, c, p;
            Edge(int v, int r, long f, long c, long p) {
                this.v = v;
                this.r = r;
                this.f = f;
                this.c = c;
                this.p = p;
            }
        }

        static void init(int n) {
            mc = 0;
            adj = new ArrayList[n];
            for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
            sz = new int[n];
            vis = new boolean[n];
            par = new int[n];
            pot = new long[n];
            dist = new long[n];
        }

        static void addEdge(int a, int b, long c, long p) {
            mc = Math.max(mc, c);
            adj[a].add(new Edge(b, sz[b]++, 0, c, p));
            adj[b].add(new Edge(a, sz[a]++, 0, 0, -p));
        }

        static long mcf(int s, int t, long[] price, int n, boolean sparse) {
            Arrays.fill(vis, false);
            Arrays.fill(dist, Long.MAX_VALUE / 2);
            dist[s] = 0;
            if (sparse) {
                PriorityQueue<Pair> pq = new PriorityQueue<>((a, b) -> Long.compare(a.dist, b.dist));
                pq.add(new Pair(s, 0));
                while (!pq.isEmpty()) {
                    Pair cur = pq.poll();
                    int u = cur.u;
                    if (vis[u]) continue;
                    vis[u] = true;
                    for (Edge e : adj[u]) {
                        if (e.f < e.c && dist[e.v] > dist[u] + pot[u] - pot[e.v] + e.p) {
                            dist[e.v] = dist[u] + pot[u] - pot[e.v] + e.p;
                            par[e.v] = e.r;
                            pq.add(new Pair(e.v, dist[e.v]));
                        }
                    }
                }
            } else {
                for (int u = s; u != -1; ) {
                    vis[u] = true;
                    for (Edge e : adj[u]) {
                        if (e.f < e.c && dist[e.v] > dist[u] + pot[u] - pot[e.v] + e.p) {
                            dist[e.v] = dist[u] + pot[u] - pot[e.v] + e.p;
                            par[e.v] = e.r;
                        }
                    }
                    u = -1;
                    long best = Long.MAX_VALUE / 2;
                    for (int i = 0; i < n; i++) {
                        if (!vis[i] && dist[i] < best) {
                            best = dist[i];
                            u = i;
                        }
                    }
                }
            }
            if (dist[t] >= Long.MAX_VALUE / 2) return 0;
            long df = Long.MAX_VALUE / 2;
            for (int u = t; u != s; ) {
                Edge r = adj[u].get(par[u]);
                df = Math.min(df, adj[r.v].get(r.r).c - adj[r.v].get(r.r).f);
                u = r.v;
            }
            for (int u = t; u != s; ) {
                Edge r = adj[u].get(par[u]);
                Edge e = adj[r.v].get(r.r);
                e.f += df;
                r.f -= df;
                price[0] += df * e.p;
                u = r.v;
            }
            for (int i = 0; i < n; i++) {
                pot[i] = Math.min(Long.MAX_VALUE / 2, dist[i] + pot[i]);
            }
            return df;
        }

        static long minCostFlow(int s, int t, long[] price, int n, boolean sparse) {
            long flow = 0;
            price[0] = 0;
            while (true) {
                long df = mcf(s, t, price, n, sparse);
                if (df == 0) break;
                flow += df;
            }
            return flow;
        }

        static class Pair {
            int u;
            long dist;
            Pair(int u, long dist) {
                this.u = u;
                this.dist = dist;
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int c = Integer.parseInt(st.nextToken());
        int d = Integer.parseInt(st.nextToken());

        final int T = 99;
        final int C = 12;
        final int source = 0;
        final int sink = n * T + 1;

        Flow.init(sink + 1);

        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < k; i++) {
            int a = Integer.parseInt(st.nextToken());
            Flow.addEdge(source, a, 1, 0);
        }

        for (int t = 0; t < T; t++) {
            Flow.addEdge(1 + t * n, sink, Long.MAX_VALUE / 2, 0);
            if (t > 0) {
                for (int i = 1; i <= n; i++) {
                    Flow.addEdge(i + (t - 1) * n, i + t * n, Long.MAX_VALUE / 2, c);
                }
            }
        }

        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(br.readLine());
            int a = Integer.parseInt(st.nextToken());
            int b = Integer.parseInt(st.nextToken());
            for (int j = 0; j < C; j++) {
                int cost = (j + 1) * (j + 1) - j * j;
                for (int t = 1; t < T; t++) {
                    Flow.addEdge(a + (t - 1) * n, b + t * n, 1, cost * d + c);
                    Flow.addEdge(b + (t - 1) * n, a + t * n, 1, cost * d + c);
                }
            }
        }

        long[] price = new long[1];
        long flow = Flow.minCostFlow(source, sink, price, sink + 1, true);
        // assert flow == k;
        System.out.println(price[0]);
    }
}
